#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>

#define RING_CAPACITY 256
#define MAX_MSG_SIZE 4096
#define HEADER_MAGIC 0xDEADBEEF

typedef struct {
    uint32_t magic;
    uint16_t msg_len;
    uint16_t seq_num;
    uint8_t  flags;
    uint8_t  reserved[3];
} __attribute__((packed)) PacketHeader;

typedef struct {
    char *data;
    size_t len;
} Message;

typedef struct {
    Message slots[RING_CAPACITY];
    volatile uint32_t write_idx;
    volatile uint32_t read_idx;
    size_t total_bytes;
    size_t max_bytes;
} RingBuffer;

static int ring_init(RingBuffer *rb, size_t max_bytes) {
    memset(rb, 0, sizeof(RingBuffer));
    rb->max_bytes = max_bytes;
    return 0;
}

static inline uint32_t ring_mask(uint32_t idx) {
    return idx & (RING_CAPACITY - 1);
}

static inline uint32_t ring_count(const RingBuffer *rb) {
    return rb->write_idx - rb->read_idx;
}

static int ring_push(RingBuffer *rb, const uint8_t *data, size_t len) {
    if (ring_count(rb) >= RING_CAPACITY) {
        return -1;
    }
    if (rb->total_bytes + len > rb->max_bytes) {
        return -2;
    }
    uint32_t slot = ring_mask(rb->write_idx);
    rb->slots[slot].data = (char *)malloc(len);
    if (!rb->slots[slot].data) return -3;
    memcpy(rb->slots[slot].data, data, len);
    rb->slots[slot].len = len;
    rb->total_bytes += len;
    rb->write_idx++;
    return 0;
}

static int ring_pop(RingBuffer *rb, char *out, size_t out_cap, size_t *out_len) {
    if (ring_count(rb) == 0) return -1;
    uint32_t slot = ring_mask(rb->read_idx);
    if (rb->slots[slot].len > out_cap) return -2;
    memcpy(out, rb->slots[slot].data, rb->slots[slot].len);
    *out_len = rb->slots[slot].len;
    free(rb->slots[slot].data);
    rb->slots[slot].data = NULL;
    rb->total_bytes -= rb->slots[slot].len;
    rb->slots[slot].len = 0;
    rb->read_idx++;
    return 0;
}

static int validate_header(const PacketHeader *hdr, size_t raw_len) {
    if (raw_len < sizeof(PacketHeader)) return -1;
    if (hdr->magic != HEADER_MAGIC) return -2;
    if (hdr->msg_len > MAX_MSG_SIZE) return -3;
    if (sizeof(PacketHeader) + hdr->msg_len > raw_len) return -4;
    return 0;
}

typedef struct {
    uint16_t fragment_offset;
    uint16_t fragment_len;
    uint16_t total_len;
    uint8_t  fragment_id;
    uint8_t  num_fragments;
} FragmentInfo;

typedef struct {
    uint8_t *reassembly_buf;
    size_t   buf_capacity;
    uint8_t  fragments_received;
    uint8_t  total_fragments;
    uint16_t total_len;
    uint8_t  fragment_id;
    int      active;
} ReassemblyContext;

static int reassembly_init(ReassemblyContext *ctx, size_t max_size) {
    ctx->reassembly_buf = (uint8_t *)calloc(1, max_size);
    if (!ctx->reassembly_buf) return -1;
    ctx->buf_capacity = max_size;
    ctx->fragments_received = 0;
    ctx->total_fragments = 0;
    ctx->total_len = 0;
    ctx->fragment_id = 0;
    ctx->active = 0;
    return 0;
}

static int reassembly_add_fragment(ReassemblyContext *ctx, const FragmentInfo *frag,
                                    const uint8_t *data, size_t data_len) {
    if (!ctx->active) {
        ctx->active = 1;
        ctx->fragment_id = frag->fragment_id;
        ctx->total_fragments = frag->num_fragments;
        ctx->total_len = frag->total_len;
        if (ctx->total_len > ctx->buf_capacity) {
            ctx->active = 0;
            return -1;
        }
        /* Zero the buffer for each new reassembly so unfilled regions are
           never disclosed as stale heap data. */
        memset(ctx->reassembly_buf, 0, ctx->buf_capacity);
    }
    if (frag->fragment_id != ctx->fragment_id) return -2;
    if (frag->num_fragments != ctx->total_fragments) return -3;
    if (frag->total_len != ctx->total_len) return -4;

    /* Validate fragment bounds - check for uint16_t overflow */
    uint32_t end_offset = (uint32_t)frag->fragment_offset + (uint32_t)frag->fragment_len;
    if (end_offset > ctx->total_len) return -5;
    if (frag->fragment_len != data_len) return -6;
    if (end_offset > ctx->buf_capacity) return -7;

    memcpy(ctx->reassembly_buf + frag->fragment_offset, data, frag->fragment_len);
    ctx->fragments_received++;
    return 0;
}

static int process_packet(RingBuffer *rb, ReassemblyContext *rctx,
                          const uint8_t *raw, size_t raw_len) {
    const PacketHeader *hdr = (const PacketHeader *)raw;
    int rc = validate_header(hdr, raw_len);
    if (rc != 0) return rc;

    const uint8_t *payload = raw + sizeof(PacketHeader);
    uint16_t msg_len = hdr->msg_len;

    if (hdr->flags & 0x01) {
        /* Fragmented packet */
        if (msg_len < sizeof(FragmentInfo)) return -10;
        const FragmentInfo *frag = (const FragmentInfo *)payload;
        const uint8_t *frag_data = payload + sizeof(FragmentInfo);
        size_t frag_data_len = msg_len - sizeof(FragmentInfo);

        rc = reassembly_add_fragment(rctx, frag, frag_data, frag_data_len);
        if (rc != 0) return rc;

        if (rctx->fragments_received >= rctx->total_fragments) {
            rc = ring_push(rb, rctx->reassembly_buf, rctx->total_len);
            rctx->active = 0;
            rctx->fragments_received = 0;
            return rc;
        }
        return 0;
    } else {
        /* Complete packet - push directly */
        return ring_push(rb, payload, msg_len);
    }
}

int handle_connection(const uint8_t *stream, size_t stream_len) {
    RingBuffer rb;
    ReassemblyContext rctx;

    ring_init(&rb, 1024 * 1024);
    if (reassembly_init(&rctx, MAX_MSG_SIZE) != 0) return -1;

    size_t offset = 0;
    while (offset < stream_len) {
        if (stream_len - offset < sizeof(PacketHeader)) break;
        const PacketHeader *hdr = (const PacketHeader *)(stream + offset);
        if (hdr->magic != HEADER_MAGIC) break;

        size_t pkt_len = sizeof(PacketHeader) + hdr->msg_len;
        if (offset + pkt_len > stream_len) break;

        process_packet(&rb, &rctx, stream + offset, pkt_len);
        offset += pkt_len;
    }

    /* Process messages from ring buffer */
    char out_buf[MAX_MSG_SIZE];
    size_t out_len;
    while (ring_pop(&rb, out_buf, sizeof(out_buf), &out_len) == 0) {
        /* Process message */
    }

    /* Cleanup */
    free(rctx.reassembly_buf);
    for (uint32_t i = 0; i < RING_CAPACITY; i++) {
        if (rb.slots[i].data) free(rb.slots[i].data);
    }
    return 0;
}
